const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
async function modules(){return {m:await import('../world-model.mjs'),n:await import('../world-navigation.mjs'),s:await import('../world-simulation.mjs')};}
async function fixture(){const {domesticRecipe,DOMESTIC_SCENES}=await import('../domestic-scenes.js'),{emptyBoard,editBoard}=await import('../playground-model.js'),{planComposition}=await import('../board-composition.js'),{resolveBoardEconomy}=await import('../board-economy.js');let board=emptyBoard('world-test');for(const [type,preset,q,r,seed]of [['home','courtyard',0,0,41],['woodland','coppice',0,1,63]]){const recipe=domesticRecipe(type,preset,seed);recipe.landscape.vegetation=0;board=editBoard(board,'place',{newInstanceId:type,q,r,card:{id:type,type,name:type,revision:1,cells:[{q:0,r:0}],rendition:{meshes:[]},recipe,capabilities:DOMESTIC_SCENES[type].capabilities}});}const assembly=planComposition(board).assembly,index=JSON.parse(fs.readFileSync(path.join(__dirname,'../domestic-assets/index.json'))),resolved=resolveBoardEconomy(board,assembly,()=>0,index,{}),{m,n}=await modules();return {board,assembly,resolved,world:m.syncWorld(board,assembly),graph:n.worldNavigation(resolved)};}
function conserved(w,m){const r=m.worldReport(w);assert.equal(r.initialFuel+r.produced-r.consumed,r.stock+r.stored+r.cargo);}
test('Per-object inherited affinities, explicit opt-out, multiple groups and save round trip',async()=>{const {world,board,assembly}=await fixture(),{m}=await modules();const home=m.placeId('home'),prop=Object.values(world.entities).find(e=>e.kind==='item'&&e.instanceId==='home');assert(prop);let w=m.setAffinities(world,home,'tribal',['Willow','Reed']);assert.equal(m.affinities(w,prop.id,'tribal').length,2);w=m.setAffinities(w,prop.id,'tribal',[]);assert.deepEqual(m.affinities(w,prop.id,'tribal'),[]);assert.equal(m.affinities(w,home,'tribal').length,2);w=m.setAffinities(w,prop.id,'tribal',['New kin']);w=m.syncWorld({...board,world:JSON.parse(JSON.stringify(w))},assembly);assert.equal(w.groups[m.affinities(w,prop.id,'tribal')[0].groupId].name,'New kin');assert.equal(Object.keys(w.agents).length,1);assert.throws(()=>m.setAffinities(w,home,'national',['x'.repeat(61)]));});
test('Actual composed Home–Woodland route transfers fuel only on collection and arrival',async()=>{const {world,graph,resolved}=await fixture(),{m,n,s}=await modules();assert.equal(resolved.model.connections.length,1,JSON.stringify(resolved.accessWarnings));const route=n.placeRoute(world,graph,m.placeId('home'),m.placeId('woodland'));assert(route?.distance>50);assert(route.points.length>3);let w=s.advanceWorld(world,graph,1);assert.equal(w.inventories[m.placeId('home')].fuel,0);assert.equal(w.inventories[m.placeId('woodland')].fuel,12);for(let t=0;t<1200&&!Object.values(w.agents)[0].cargo;t++)w=s.advanceWorld(w,graph,1);assert.equal(Object.values(w.agents)[0].cargo,2);assert.equal(w.delivered,0);assert.equal(w.inventories[m.placeId('home')].fuel,0);conserved(w,m);for(let t=0;t<1200&&!w.delivered;t++)w=s.advanceWorld(w,graph,1);assert.equal(w.delivered,2);assert.equal(Object.values(w.agents)[0].cargo,0);conserved(w,m);});
test('Deterministic clock, batched steps and mid-journey persistence',async()=>{const {world,graph}=await fixture(),{s}=await modules();let stepped=world;for(let i=0;i<180;i++)stepped=s.advanceWorld(stepped,graph,1);const batched=s.advanceWorld(world,graph,180);assert.deepEqual(stepped,batched);const reloaded=JSON.parse(JSON.stringify(s.advanceWorld(world,graph,90)));assert.deepEqual(s.advanceWorld(reloaded,graph,90),batched);});
test('Disconnected places cannot transfer; route break preserves courier and cargo until restored',async()=>{const {world,graph}=await fixture(),{s,m}=await modules();const broken={nodes:{},adj:{},hubs:{},signature:'disconnected'};let idle=s.advanceWorld(world,broken,300);assert.equal(idle.delivered,0);assert.equal(Object.values(idle.agents)[0].phase,'waiting');conserved(idle,m);let w=world;for(let t=0;t<1000&&!Object.values(w.agents)[0].cargo;t++)w=s.advanceWorld(w,graph,1);assert.equal(Object.values(w.agents)[0].cargo,2);const before=structuredClone(Object.values(w.agents)[0]);w=s.advanceWorld(w,broken,40);const after=Object.values(w.agents)[0];assert.equal(after.id,before.id);assert.equal(after.cargo,2);assert.deepEqual(after.position,before.position);assert.equal(after.phase,'waiting');conserved(w,m);w=s.advanceWorld(w,graph,600);assert(w.delivered>=2);conserved(w,m);});
test('Removal and restoration retain inventories and overrides without new grants',async()=>{const {board,assembly,world,graph}=await fixture(),{s,m}=await modules();let w=s.advanceWorld(world,graph,90);w=m.setAffinities(w,m.placeId('woodland'),'national',['Vale']);const fuel=w.inventories[m.placeId('woodland')].fuel;w=m.syncWorld({...board,world:w,instances:board.instances.filter(i=>i.instanceId!=='woodland')},{plans:assembly.plans.filter(p=>!p.id.startsWith('woodland:'))});assert.equal(w.entities[m.placeId('woodland')].active,false);assert.equal(w.inventories[m.placeId('woodland')].fuel,fuel);conserved(w,m);w=m.syncWorld({...board,world:w},assembly);assert.equal(w.inventories[m.placeId('woodland')].fuel,fuel);assert.equal(m.affinities(w,m.placeId('woodland'),'national').length,1);conserved(w,m);});
test('Undo owns independent world snapshots; clock checkpoint precedes next edit',async()=>{const {board,world}=await fixture(),{compositionHistory}=await import('../board-state.js');const b={...board,world},history=compositionHistory(b);b.world.seconds=12;history.checkpoint(b);const next=structuredClone(b);next.revision++;next.world.seconds=30;history.commit(next);next.world.seconds=77;assert.equal(history.peek('undo').world.seconds,12);history.accept('undo',history.peek('undo'));assert.equal(history.peek('redo').world.seconds,30);});
test('Duplicate Home gets a new courier with no cloned cargo or journey',async()=>{const {board,world,graph}=await fixture(),{m,s}=await modules(),{editComposition}=await import('../board-state.js'),{planComposition}=await import('../board-composition.js');const w=s.advanceWorld(world,graph,50),next=editComposition({...board,world:w},'duplicate',{instanceId:'home',newInstanceId:'new-home',q:1,r:0}),synced=m.syncWorld(next,planComposition(next).assembly);assert.equal(Object.keys(synced.agents).length,2);const old=Object.values(synced.agents).find(a=>a.homeId===m.placeId('home')),fresh=Object.values(synced.agents).find(a=>a.homeId===m.placeId('new-home'));assert.notEqual(old.id,fresh.id);assert.equal(fresh.cargo,0);assert.equal(fresh.metres,0);assert.equal(synced.initialFuel,w.initialFuel);});
test('Shared affiliations can tip nearby supplier choice; preference can be disabled',async()=>{const {m,s}=await modules();let w={version:1,id:'choice',seconds:0,entities:{},groups:{},agents:{person:{id:'person',homeId:'home',at:'home',position:{x:0,y:0,z:0},cargo:0,phase:'idle',trip:null,metres:0,deliveries:0}},inventories:{},produced:0,consumed:0,initialFuel:24,delivered:0,events:[],policy:{preferFamiliar:true}};for(const k of ['home','near','familiar']){w.entities[k]={id:k,active:true,kind:'place',type:k==='home'?'home':'woodland',name:k,hub:k,affinities:{}};w.inventories[k]={fuel:k==='home'?0:12,produced:0,consumed:0};}w.entities.person={id:'person',active:true,kind:'person',parentId:'home',affinities:{}};for(const k of ['home','familiar'])w=m.setAffinities(w,k,'tribal',['Willow']);const g={nodes:{home:{x:0,y:0,z:0},near:{x:100,y:0,z:0},familiar:{x:0,y:0,z:110}},adj:{home:[{id:'near',cost:100},{id:'familiar',cost:110}],near:[{id:'home',cost:100}],familiar:[{id:'home',cost:110}]},hubs:{home:'home',near:'near',familiar:'familiar'},signature:'choice'};assert.equal(s.advanceWorld(w,g,1).agents.person.trip.target,'familiar');w.policy.preferFamiliar=false;assert.equal(s.advanceWorld(w,g,1).agents.person.trip.target,'near');assert.equal(s.advanceWorld(w,g,1).inventories.home.fuel,0);});
